  // Revalidate the current page so it reflects the updated state without redirecting
  revalidatePath('/');
}

import { getNotificationPreference, toggleNotificationPreference } from './actions';

export default async function Home() {
  const isEnabled = await getNotificationPreference();

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are currently {isEnabled ? 'ON' : 'OFF'}.</p>

      <form action={toggleNotificationPreference}>
        <button type="submit">
          Turn Notifications {isEnabled ? 'OFF' : 'ON'}
        </button>
      </form>
    </main>
  );
}

